  ui_story_5068_50680201_7_dialog_content = "ฉันเพียงแค่ต้องหาที่มาของหมอกสีดำแล้วรายงานให้คุณเชโอลทราบ ฉันไม่ต้องเป็นห่วงเรื่องที่จะเกิดขึ้นหลังจากนั้น",
  ui_story_5068_50680201_8_dialog_content = "นอกจากนี้ ฉันก็ไม่สามารถยอมแพ้กลางคันได้! ฉันต้องเข้มแข็งขึ้น!",
