  ui_story_5068_50680201_10_dialog_content = "ฮู้ม... ดูเหมือนว่าฉันกำลังใกล้ต้นกำเนิดของหมอกสีดำแล้ว",
  ui_story_5068_50680201_11_dialog_content = "ฉันไม่คาดคิดเลยว่าสิ่งต่าง ๆ จะดำเนินไปได้ราบรื่นขนาดนี้ ฉันเดาว่าคุณเชโอลไม่ได้โกหกเกี่ยวกับระดับความอันตรายของงานนี้หลังจากนั้น",
  ui_story_5068_50680201_12_dialog_content = "ช่วยด้วย! มีใครอยู่ไหม? ช่วยฉันด้วย!",
  ui_story_5068_50680201_13_dialog_content = "เอ๊ะ? ผมหูแว่วหรือเปล่า หรือมีคนเรียกขอความช่วยเหลือจริงๆ?",
