  ui_story_5068_50680201_19_dialog_content = "หา?",
  ui_story_5068_50680201_20_dialog_content = "อิคลิพไซท์มาถึงที่นี่ได้ยังไงเนี่ย?!",
  ui_story_5068_50680202_1_dialog_content = "(น่าทึ่งมาก! เธอกำจัดอิคลิพไซท์ทุกตัวก่อนที่ฉันยังไม่มีเวลาตอบสนอง!)",
  ui_story_5068_50680202_2_dialog_content = "ไม่ควรมีอิคลิพไซท์เพิ่มเติมแล้วนะ อย่างน้อยตอนนี้ คุณโอเคมั้ย?",
  ui_story_5068_50680202_3_dialog_content = "... ฉันสบายดี ไม่ต้องห่วง มันเกือบจะเป็นไปไม่ได้ ขอบคุณที่ช่วยฉันนะ <color=#FFB400>ผู้ช่วยคุณหญิง</color>.",
  ui_story_5068_50680202_4_dialog_content = "ไม่ต้องพูดถึงเลย ไม่นึกเลยว่าอิคลิพไซท์จะเจาะเข้ามาที่นี่ แม้ว่าจะยังอยู่ในส่วนของอัมบราตัน พูดถึงโชคร้ายเถอะ!",
  ui_story_5068_50680202_5_dialog_content = "คุณไปเจอพวกเขาได้ยังไงนะ?",
