  ui_story_5068_50680302_9_dialog_content = "...คุณน่าจะดีแล้วนะ กลับบ้านแล้วพักผ่อนเยอะๆ และอย่าทำงานหนักในวันถัดไปสองวันนะ",
  ui_story_5068_50680302_10_dialog_content = "ขอบคุณคุณ<color=#FFB400>หมอ</color> ตอนนี้ฉันรู้สึกดีขึ้นมากแล้ว แต่...",
  ui_story_5068_50680302_11_dialog_content = "อะไรเนี่ย? คุณยังรู้สึกไม่สบายอยู่หรือ?",
