  ui_story_5068_50680302_13_dialog_content = "ไม่ต้องห่วงถ้าคุณจ่ายค่าจ้างฉันไม่ได้ตอนนี้ ให้เขียนไว้ในบัญชีของคุณแล้วจ่ายให้ฉันทีหลังเหมือนปกติก็ได้ครับ",
  ui_story_5068_50680302_14_dialog_content = "ทุกคนที่นี่รู้จักกันหมดแล้ว ดังนั้นเมื่อไหร่ที่คุณมีเงินก็กลับมาที่นี่เถอะ",
  ui_story_5068_50680302_15_dialog_content = "ขอบคุณมากค่ะ! ฉันขอขอบคุณอย่างยิ่ง! ฉันเสียเครดิตเสมอ และมันน่าอายจริง ๆ...",
  ui_story_5068_50680302_16_dialog_content = "อย่าเครียดเรื่องนั้นมากเกินไป การปล่อยปัญหาสุขภาพไว้ไม่รักษาไม่ใช่ความคิดที่ดี เมื่อคุณต้องการความช่วยเสริมให้มาหาฉันเสมอนะ โอเค?",
  ui_story_5068_50680302_17_dialog_content = "ใช่เลย! โอ้... ดูเหมือนว่ามีคนไข้คนใหม่ ฉันจะไม่ให้คุณหมอเสียเวลามากขึ้นนะคะ",
