  ui_story_5068_50680302_21_dialog_content = "(ถ้ามันเป็นเธอจริง ๆ ... เธอต้องการอะไรกันเนี่ย?)",
  ui_story_5068_50680302_22_dialog_content = "(เธอทำแบบนี้ตั้งใจหรือเปล่า? เธอจะทำให้คนป่วยเพื่อให้มีผู้ป่วยเพิ่มขึ้นหรือไม่?)",
  ui_story_5068_50680302_23_dialog_content = "(ไม่สิ ไม่น่าจะใช่ ฉันเพิ่งเห็นเธอยกเว้นค่ารักษาพยาบาลให้เด็กผู้หญิงคนนั้นชั่วคราว และดูเหมือนว่าไม่ใช่ครั้งแรกเหมือนกัน)",
  ui_story_5068_50680302_24_dialog_content = "หมอถามคุณคำถามแล้วนะ หยุดจ้องเธออย่างนั้นเถอะ! ฉันเตือนแล้วนะ ถ้าคุณมองสิ่งที่ไม่ควรมอง แม้กระทั่งเธอก็ไม่สามารถแก้ไขสิ่งที่เกิดขึ้นกับดวงตาของคุณได้!",
  ui_story_5068_50680302_25_dialog_content = "พอแล้วนะ คุณกำลังทำให้คนไข้ของเรากลัว ตอนนี้... มีอะไรผิดปกติกับเขาอย่างแน่นอน?",
  ui_story_5068_50680302_26_dialog_content = "เขาบ่นว่าปวดท้องตั้งแต่เช้า...",
  ui_story_5068_50680302_27_dialog_content = "ใช่... นั่นแหละ มันคือท้องของฉัน",
  ui_story_5068_50680302_28_dialog_content = "นั่นเตือนใจฉัน ใครบอกคุณเรื่องคลินิกในตอนแรกเหรอ?",
  ui_story_5068_50680302_29_dialog_content = "อืม... ค-คนแปลกหน้าที่เป็นมิตรค่ะ เขาเห็นว่าฉันเจ็บปวดมาก จึงบอกฉันเกี่ยวกับคลินิกใกล้ ๆ และวิธีการหามันค่ะ",
  ui_story_5068_50680302_30_dialog_content = "—!",
  ui_story_5068_50680302_31_dialog_content = "...",
  ui_story_5068_50680302_32_dialog_content = "(เอ่อ, มันเป็นอะไรกัน? ฉันพูดอะไรที่ไม่ควรพูดไปหรือเปล่า...?)",
  ui_story_5068_50680302_33_dialog_content = "อื้อ... อื้อ, อ๊าาา!",
  ui_story_5068_50680302_34_dialog_content = "เจ็บค่ะ! อ๊ากกก! มันทำให้ฉันตายเลย!",
  ui_story_5068_50680302_35_dialog_content = "นี่คือ-",
  ui_story_5068_50680302_36_dialog_content = "เขาเพิ่งฟื้นตัวไม่นานนี้เอง มันจะเป็นอย่างไรได้? ถ้าฉันไม่รักษาเขาทันที...",
  ui_story_5068_50680302_37_dialog_content = "ฉันรู้สึกไม่สบายมาก... หมอคะ, ฉันจะตายเหรอ? ขอร้องค่ะ, ฉันไม่อยากตาย...",
  ui_story_5068_50680302_38_dialog_content = "อ๊าาาาาาาา!!!",
  ui_story_5068_50680302_39_dialog_content = "หยุดคิดเรื่องแบบนั้นเถอะ! ฉันจะรักษาคุณทันที ไม่ต้องกลัวนะ ทุกอย่างจะเป็นไปด้วยดี...",
  ui_story_5068_50680302_40_dialog_content = "(นั่น—)",
  ui_story_5068_50680302_41_dialog_content = "หา?",
  ui_story_5068_50680302_42_dialog_content = "สิ่งต่าง ๆ เข้าหูคุณแล้วก็ออกหูเลยใช่มั้ย? ฉันบอกให้คุณเก็บตาเก็บตัวแล้วนี่เนี่ย ไม่ได้เหรอ?!",
  ui_story_5068_50680302_43_dialog_content = "ขอโทษค่ะ! ฉันไม่ได้ตั้งใจมองนะ!",
  ui_story_5068_50680302_44_dialog_content = "(... ถ้าฉันไม่คิดผิด คุณหมอคนนี้กำลังใช้ลูมินาในการรักษาคนไข้ของเธอ หมอกนี้จะปรากฏขณะที่เธอรักษาคนไข้เท่านั้น)",
  ui_story_5068_50680302_45_dialog_content = "(แต่มันต่างจากของที่ท่านหญิงเชโอลให้ฉัน หมอกของเธอเต็มไปด้วยลูมินา ในขณะที่ตัวอย่างของท่านหญิงเชโอลไม่มีเลย)",
  ui_story_5068_50680302_46_dialog_content = "(นี่หมายความว่าฉันผิดหรือเปล่า? ไม่, ยังเร็วเกินไปที่จะตัดสินใจ! อาจเป็นเพราะลูมินาปรากฏขึ้นเฉพาะระหว่างการรักษาเท่านั้น แล้วหลังจากนั้นมันก็หมดไป เมื่อเสร็จสิ้นการรักษา...)",
  ui_story_5068_50680302_47_dialog_content = "(เมื่อลูมินาหมดไปเสีย มันกลับกลายเป็นหมอกสีดำที่เป็นอันตราย! น่าจะเป็นไปได้ว่าหมอไม่รู้วิธีจัดการกับมัน เพราะฉะนั้นเธอจึงกำจัดมันในที่ลับ)",
  ui_story_5068_50680302_48_dialog_content = "(แต่เหล่านี้เป็นเพียงความคิดเห็นส่วนตัวของฉันเท่านั้น; ไม่ว่าจะถูกหรือผิดนั้นขึ้นอยู่กับคุณเชโอลที่จะตัดสินใจ อาจจะเป็นว่าฉันผิดเกี่ยวกับทุกอย่างนี้อย่างสิ้นเชิง)",
  ui_story_5068_50680302_49_dialog_content = "คุณสบายดีแล้วนะ ลองพักผ่อนสักหน่อย แล้วคุณจะหายขึ้นเมื่อตื่นนอน",
  ui_story_5068_50680302_50_dialog_content = "เอ่อ...",
  ui_story_5068_50680302_51_dialog_content = "ฟู่!",
  ui_story_5068_50680302_52_dialog_content = "(เธอดูโล่งใจที่เห็นคนไข้ของเธออยู่ในสภาพที่เสถียร ฉันไม่คิดว่าเธอจะหลอกลวงเรื่องนี้เสียอีก)",
  ui_story_5068_50680302_53_dialog_content = "คุณหมอรักษาคนไข้เยอะมากแล้ววันนี้ พักผ่อนก่อนเถอะครับ แล้วเดี๋ยวฉันจัดการคนไข้คนสุดท้ายนี้ให้",
  ui_story_5068_50680302_54_dialog_content = "ไม่เป็นไร ฉันสามารถดูแลเขาได้ แต่... คุณน่าจะถูกในเรื่องที่คนไข้เยอะเกินไป วันนี้เราไม่รับคนไข้ใหม่แล้ว กรุณาปิดประตูด้วย",
  ui_story_5068_50680302_55_dialog_content = "ได้สิ",
  ui_story_5068_50680302_56_dialog_content = "(?!)",
  ui_story_5068_50680302_57_dialog_content = "ผู้ช่วยของฉันบอกว่าคุณปวดท้อง ใช่ไหม?",
  ui_story_5068_50680302_58_dialog_content = "มันเป็นโรคเรื้อรังหรือเปล่า?",
  ui_story_5068_50680302_59_dialog_content = "อืม...",
  ui_story_5068_50680302_60_dialog_content = "หรือบางทีคุณกินอะไรที่ไม่ค่อยสะอาดเสียหรือเปล่า?",
