  ui_story_5068_50680302_63_dialog_content = "ฉันมียาที่มีประสิทธิภาพสูงในการรักษาปวดท้องมากมาย ไม่ว่าสาเหตุจะเป็นอะไรก็ตาม",
  ui_story_5068_50680302_64_dialog_content = "เห็นมั้ย?",
  ui_story_5068_50680302_65_dialog_content = "เพียงแค่ฉีดเข็มเดียว ความเจ็บปวดไม่มีทางรบกวนคุณอีกต่อไป คุณยังจะไม่สามารถจำความเจ็บปวดที่เคยรู้สึกมาก่อนได้เลย",
