  ui_story_5068_50680401_9_dialog_content = "คุณดูเหมือนว่าไม่มีเจตนาร้าย ถ้าคิดจากที่คุณไม่ได้พยายามโจมตีเราตลอดเวลานี้... ใช่ไหม?",
  ui_story_5068_50680401_10_dialog_content = "...ใช่แล้ว!",
  ui_story_5068_50680401_11_dialog_content = "ไม่ใช่แบบนี้อีกแล้ว, ดอกเตอร์.",
