  ui_story_5068_50680401_14_dialog_content = "นอกจากนี้ สถานที่นี้เป็นของเรา ตราบใดที่คุณอยู่ข้างๆฉัน ฉันก็ไม่มีอะไรที่ต้องห่วงใย",
  ui_story_5068_50680401_15_dialog_content = "...",
