  ui_story_5068_50680401_21_dialog_content = "ถ้าการแสดงของคุณดีขึ้นเราคงสงสัยคุณมากขึ้น ตามความจริงแล้ว ส่วนที่เปิดเผยมากที่สุดในการแสดงของคุณคือคำพูดเพียงประโยคเดียว",
  ui_story_5068_50680401_22_dialog_content = "อืม... แค่คนแปลกหน้าที่เป็นมิตรค่ะ เขาเห็นว่าฉันเจ็บปวดมาก ก็เลยบอกฉันเกี่ยวกับคลินิกใกล้ ๆ และวิธีการหามันค่ะ",
