  ui_story_5068_50680401_42_dialog_content = "(เมื่อคุณหลับแล้ว ฉันจะให้เอลีนอร์พาคุณไปที่ปลอดภัย คุณไม่ควรเข้ามาในคลินิกนี้)",
  ui_story_5068_50680401_43_dialog_content = "(<color=#FFB400>เรเบคก้า</color> ยังคงเป็นคนที่ใจดีเกินไป)",
  ui_story_5068_50680401_44_dialog_content = "(ฉันรู้ว่าผู้ชายคนนี้ไม่ดีตั้งแต่เขาเดินเข้ามาและพูดเรื่องไร้สาระ ถ้ามองให้ฉันตัดสินใจ ฉันคงไล่เขาออกไปพร้อมกับขยะคนอื่นๆ โดยไม่คิดคำถาม)",
  ui_story_5068_50680401_45_dialog_content = "(ท่านหญิงเรเบคก้าดูเหมือนไม่ต้องการทำร้ายฉัน และผู้ช่วยของเธอก็ฟังคำสั่งของเธออย่างจริงจัง)",
  ui_story_5068_50680401_46_dialog_content = "(ถ้าฉันไม่ได้รบกวนพวกเขา เธอคงไม่ต้องทำแบบนี้กับฉัน แต่บางที... บางทีฉันอาจยังมีโอกาสในการสร้างความเชื่อมั่นกับเธอได้หรือเปล่า?)",
  ui_story_5068_50680401_47_dialog_content = "(ฉันมีช็อตเดียวที่นี่!)",
  ui_story_5068_50680401_48_dialog_content = "เดี๋ยวนะ! ช่วงนี้คุณรักษาคนไข้ที่มีอาการปริศนาเยอะหรือเปล่า?",
  ui_story_5068_50680401_49_dialog_content = "หยุดพยายามหน่วงเวลา!",
  ui_story_5068_50680401_50_dialog_content = "... ไม่เป็นไร ให้เขาพูดเถอะ",
  ui_story_5068_50680401_51_dialog_content = "เอิ่ม ดีครับ ฉันไม่รู้ว่าทำไมคุณสองคนถึงปิดบังเรื่องนี้ แต่ฉันสามารถบอกได้ว่าคุณหมอจริง ๆ แล้วมีความห่วงใยต่อผู้ป่วยของคุณนะครับ",
  ui_story_5068_50680401_52_dialog_content = "บางทีเราอาจสามารถร่วมมือกันค้นหาต้นตอของโรคประหลาด ๆ นี้ได้มั้ย?",
  ui_story_5068_50680401_53_dialog_content = "อืมม... คุณพูดว่างานของคุณเกี่ยวกับการสืบสวนโรคแปลกประหลาดใช่ไหม? คุณมีความคืบหน้าอื่น ๆ อีกหรือไม่?",
  ui_story_5068_50680401_54_dialog_content = "แค่นี้นะ",
  ui_story_5068_50680401_X54_dialog_content = "คุณเคยเห็นอะไรแบบนี้มาก่อนรึเปล่าคุณหมอเรเบคก้า? ในฐานะหมอ คุณควรรู้เรื่องนี้มากกว่าฉันเสียอีกครับ",
  ui_story_5068_50680401_55_dialog_content = "—!!!",
  ui_story_5068_50680401_56_dialog_content = "อ-อะไรคุณทำกับนี้?! คุณพบมันที่ไหน?!",
  ui_story_5068_50680401_57_dialog_content = "เดี๋ยวนะ! เธอรู้ชื่อเรเบคก้าได้ยังไง?!",
  ui_story_5068_50680401_58_dialog_content = "(อ่า! หลุดปากพูดซะแล้ว!)",
  ui_story_5068_50680401_59_dialog_content = "คายมันออกมาก่อนที่ฉันจะบังคับให้คุณคายออกมา!",
  ui_story_5068_50680401_60_dialog_content = "รอสักครู่, เว้นแต่ว่า... คุณอยู่กับ <color=#FFB400>หมาป่าดำ</color> ใช่มั้ย?!",
  ui_story_5068_50680401_61_dialog_content = "หมาป่าสีดำ? พวกเขาคือใคร?",
  ui_story_5068_50680401_62_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_5068_50680401_63_dialog_content = "ใครบอกว่าที่นี่เป็นคลินิก? ที่ทิ้งขยะแบบนี้เหรอ?",
  ui_story_5068_50680401_64_dialog_content = "มันทรุดโทรมเล็กน้อย แต่ดูของข้างในสิ; นี่คือคลินิกจริง ๆ!",
  ui_story_5068_50680401_65_dialog_content = "หน้ากากพวกนั้น... หมาป่าสีดำจริงๆ คือผู้ควบคุมทั้งหมดเหรอ?",
  ui_story_5068_50680401_66_dialog_content = "อย่าพยายามทำอะไรตลกๆ! เพื่อนของคุณที่นี่บอกเราทุกอย่างแล้วนะ!",
  ui_story_5068_50680401_67_dialog_content = "เดี๋ยวหยุด! ฉันไม่รู้จักคนพวกนี้เลย! เราไม่ได้ทำงานร่วมกัน ฉันสาบานนะ!",
  ui_story_5068_50680401_68_dialog_content = "เฮ้อ คุณหมอ! คุณหมอ ออกมาเร็ว! ใครเป็นหมอที่นี่น่ะ?",
  ui_story_5068_50680401_69_dialog_content = "ฉันได้ยินว่าหมอที่นี่สามารถรักษาโรคที่เกิดจากหมอกสีดำ ขยับตัวออกมาที่นี่เดี๋ยวนี้!",
  ui_story_5068_50680401_70_dialog_content = "ที่นี่ไม่มีหมอนะ! แต่ถ้าคุณกำลังหาเหตุผลในการหาหมอ ฉันยินดีที่จะให้คำแนะนำให้คุณ!",
  ui_story_5068_50680401_71_dialog_content = "หายไปเถอะ ไอ้พวกเศษสวะ!",
  ui_story_5068_50680401_72_dialog_content = "โอ๊ย!",
  ui_story_5068_50680401_73_dialog_content = "ทำไมคนบ้าคนนี้ถึงกัดทุกคนที่เธอเห็นเนี่ย?! โชคดีที่ฉันตอบสนองเร็วพอ!",
  ui_story_5068_50680401_74_dialog_content = "กล้ามากลอบเข้ามาหาเราเหรอ?! เราไม่ใช่เป้าหมายง่ายๆ ของใคร! ฆ่าพวกมันเลยตอนนี้!",
  ui_story_5068_50680401_75_dialog_content = "มาดูกันว่าใครจะตายก่อนกันเถอะ",
  ui_story_5068_50680401_76_dialog_content = "อัก!",
  ui_story_5068_50680401_77_dialog_content = "อะไรเนี่ย?! นี่มันบ้าไปแล้ว! ทุกคนหยิบอาวุธขึ้นมา! เร็ว!!!",
  ui_story_5068_50680401_78_dialog_content = "<color=#e8d9bb>ปัง! ปัง!</color>",
  ui_story_5068_50680401_79_dialog_content = "อ๊าาา!",
  ui_story_5068_50680401_80_dialog_content = "อย่าปล่อยให้พวกมันหลุดหนีไป!!!",
  ui_story_5068_50680401_81_dialog_content = "<size=45><color=#e8d9bb>ตูม! ตูม! ตูม!</color></size>",
  ui_story_5068_50680401_82_dialog_content = "(เกิดอะไรขึ้นที่นี่เนี่ย... ทำไมสถานการณ์ถึงกลายเป็นแบบนี้ได้?!)",
  ui_story_5068_50680401_83_dialog_content = "(ประตูถูกขวางทางสนิท ฉันหนีออกไปไม่ได้แม้แต่ถ้าฉันต้องการ...)",
  ui_story_5068_50680401_84_dialog_content = "<color=#e8d9bb>ปี๊บ—ปี๊บ—</color>",
  ui_story_5068_50680401_85_dialog_content = "มาเถอะ! รับสายสิ เลดี้เชล!!",
  ui_story_5068_50680502_1_dialog_content = "กลุ่มของคนโง่เง่า! คนนี้อยู่กับพวกคุณใช่มั้ย? ถ้าคุณไม่ต้องการให้เกิดอะไรขึ้นกับเขา—",
  ui_story_5068_50680502_2_dialog_content = "ฉันบอกคุณแล้วว่าเราไม่ได้ทำงานร่วมกัน...",
  ui_story_5068_50680502_3_dialog_content = "คุณหญิงคนนี้มีปัญหาหรือเปล่า? เธอเลือกคนสุ่ม ๆ แล้วอ้างว่าเขาเป็นหนึ่งในหมาป่าดำของเรา ใครในคุณรู้จักคนนี้บ้างเหรอ?",
  ui_story_5068_50680502_4_dialog_content = "ไม่ คุณรู้จักเขาเหรอ?",
  ui_story_5068_50680502_5_dialog_content = "ช่างบังเอิญอะไรเช่นนี้; ฉันก็ไม่รู้จักเขาเหมือนกัน",
  ui_story_5068_50680502_6_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า",
  ui_story_5068_50680502_7_dialog_content = "นี่แหละที่ฉันพยายามบอกคุณตลอดเวลา! ทำไมคุณไม่เชื่อฉันเสียหน่ะ?!",
  ui_story_5068_50680502_8_dialog_content = "การจับฉันเป็นตัวประกันไม่ได้ช่วยอะไรพวกคุณเลย คุณจะช่วยเอามีดออกจากคอฉันได้มั้ย? ฉันอาจจะโดนเจ็บตัวจริงๆ...",
  ui_story_5068_50680502_9_dialog_content = "หุบปาก! ถึงแม้แกจะไม่ร่วมมือกับพวกเขา แต่แกก็ยังเป็นขยะในสายตาฉันเสียอยู่ดี!",
  ui_story_5068_50680502_10_dialog_content = "ปล่อยให้เขาไปเถอะ เราไม่ต้องการให้คนเสียหายที่ไม่เกี่ยวข้อง",
  ui_story_5068_50680502_11_dialog_content = "ใสซื่อบริสุทธิ์คือคำสุดท้ายที่ฉันจะใช้ในการบรรยายคนนี้",
  ui_story_5068_50680502_12_dialog_content = "แต่ถ้าแม้กระทั่งหมอก็พูดแบบนั้น... คิดว่าวันนี้เป็นวันโชคดีของคุณ",
  ui_story_5068_50680502_13_dialog_content = "ฉันขอให้เข้าใจนะ! ใครที่ก่อกวนกับหมาป่าดำจะไม่มีวันสิ้นสุดที่ดี!",
  ui_story_5068_50680502_14_dialog_content = "คุณรู้ไหมว่าเรากำลังคิดจะยึดครอบครองย่านนี้อย่างสงบสุข แต่ตอนนี้ ดูเหมือนว่าการทำลายมันอย่างเด็ดขาดจะเป็นตัวเลือกที่ดีกว่า!",
  ui_story_5068_50680502_15_dialog_content = "...",
  ui_story_5068_50680502_16_dialog_content = "แล้วพวกคุณบ้านั่นมาทำอะไรที่นี่เหรอ?",
  ui_story_5068_50680502_17_dialog_content = "เดี๋ยวนะ! ฉันรู้จักคุณ! คุณคือ—",
  ui_story_5068_50680502_18_dialog_content = "คุณคือเอลีนอร์!",
  ui_story_5068_50680502_19_dialog_content = "...",
  ui_story_5068_50680502_20_dialog_content = "ถูกต้อง! ฉันจำได้แล้ว! ฉันรู้จักคุณ!",
  ui_story_5068_50680502_21_dialog_content = "หืม? อีล... อะไรนะ? ไม่ได้ยินเคยเลยครับ",
  ui_story_5068_50680502_22_dialog_content = "เอลีนอร์! ฉันหมายถึง—",
  ui_story_5068_50680502_23_dialog_content = "เอ...",
  ui_story_5068_50680502_24_dialog_content = "ขอโทษจริง ๆ นะคะ...",
  ui_story_5068_50680502_25_dialog_content = "แต่ถ้าเป็นแบบนี้ต่อไป คุณก็จะทำให้เรื่องยุ่งยากขึ้นเรื่อยๆ... คุณไม่ให้ทางเลือกให้ฉันเลย...",
  ui_story_5068_50680502_26_dialog_content = "ชิ...",
  ui_story_5068_50680502_27_dialog_content = "อยู่สบาย ๆ เถอะ ฉันสัญญาว่ามันจะไม่เจ็บมากหรอก...",
  ui_story_5068_50680502_28_dialog_content = "อะไรนะ!? เธอทำอะไรกับเขาแบบนี้?!",
  ui_story_5068_50680502_29_dialog_content = "ไม่ต้องห่วง ฉันไม่มีเจตนาที่จะเอาชีวิตของใครเสียหาย",
  ui_story_5068_50680502_30_dialog_content = "ดังที่คุณเห็น ฉันเพิ่งทำให้เขาหมดสติ",
  ui_story_5068_50680502_31_dialog_content = "นี่, ผู้หญิงคนนี้, เธอบ้า... ถอยหลัง... ขยับ, ขยับ!",
  ui_story_5068_50680502_32_dialog_content = "กลับไปรายงานกับหัวหน้า! ให้ผู้บังคับบัญชาระดับสูง—",
  ui_story_5068_50680502_33_dialog_content = "อัก!!!",
  ui_story_5068_50680502_34_dialog_content = "ขอโทษนะ แต่ฉันไม่สามารถปล่อยให้พวกคุณหนีไปได้",
  ui_story_5068_50680502_35_dialog_content = "ถ้าแม้แต่หนึ่งในคุณสามารถออกไปพร้อมกับความทรงจำที่ไม่เสียหาย... มันจะทำให้เกิดปัญหามากขึ้นให้ฉัน",
  ui_story_5068_50680502_36_dialog_content = "ฉันขอโทษค่ะ นางเรเบคก้า คนนั้นคงจำฉันจากวันที่เราเดินทางอยู่ค่ะ",
  ui_story_5068_50680502_37_dialog_content = "ไม่เป็นไรเลนอร์ ฉันรู้อยู่แล้วว่าวันนี้จะต้องมาถึงในที่สุด มันเป็นแค่เรื่องของเวลาเท่านั้น",
  ui_story_5068_50680502_38_dialog_content = "(แค่การโจมตีครั้งเดียวเท่านั้น...)",
  ui_story_5068_50680502_39_dialog_content = "(ดูเหมือนว่าเรเบคก้าไม่ได้ใช้พลังเต็มที่ในการต่อสู้กับหมาป่าสีดำเหล่านั้น)",
  ui_story_5068_50680502_40_dialog_content = "(เธอดูอ่อนแอมาก แต่จริงๆ แล้วเธอแข็งแกร่งมาก... ฉันไม่คิดว่าเธอเป็นแค่หมอธรรมดา)",
  ui_story_5068_50680502_41_dialog_content = "สำหรับคุณ วางใจได้ว่าฉันไม่มีเจตนาที่จะทำเช่นนั้นกับคุณ... อย่างน้อยไม่ในตอนนี้นะ",
  ui_story_5068_50680502_42_dialog_content = "คุณไม่ต้องห่วงเรื่องคนเหล่านี้หรอก",
  ui_story_5068_50680502_43_dialog_content = "คุณยังจำการฉีดยาที่ฉันเตรียมให้คุณก่อนหน้านี้ได้ใช่ไหม? พูดเถิดเถิด มันไม่ใช่ยาจริง ๆ นะ",
  ui_story_5068_50680502_44_dialog_content = "คุณเรเบคก้าเนี่ย? คุณไม่คิดว่าคุณบอกเขามากเกินไปหรือเปล่า?",
  ui_story_5068_50680502_45_dialog_content = "ไม่ต้องกังวล ฉันรู้ว่าฉันกำลังทำอะไรอยู่",
  ui_story_5068_50680502_46_dialog_content = "เซรั่มในการฉีดนี้ไม่ใช่ยา แต่เป็น<color=#FFB400>พิษ</color>... ชนิดเดียวกันที่ฉันเพิ่งให้กับคนเหล่านี้",
  ui_story_5068_50680502_47_dialog_content = "พิษ?!",
  ui_story_5068_50680502_48_dialog_content = "ใช่ครับ พิษ... แต่มันไม่ใช่พิษที่ทำให้เสียชีวิต",
  ui_story_5068_50680502_49_dialog_content = "คนเหล่านี้... แค่หมดสติเท่านั้น ไม่มีอะไรเพิ่มเติม",
  ui_story_5068_50680502_50_dialog_content = "เมื่อวายร้ายเหล่านี้ตื่นขึ้น พวกเขาจะลืมว่าตัวเองเป็นใครและกำลังทำอะไรอยู่!",
  ui_story_5068_50680502_51_dialog_content = "ขอโทษนะ เด็กน้อย... เราทำให้คุณตกใจเมื่อกี้หรือเปล่า?",
  ui_story_5068_50680502_52_dialog_content = "ฉันไม่กลัวเลย!",
  ui_story_5068_50680502_53_dialog_content = "แล้วคุณรู้สึกดีขึ้นหรือไม่?",
  ui_story_5068_50680502_54_dialog_content = "ตอนนี้ฉันรู้สึกดีขึ้นมากแล้วค่ะ! ขอบคุณคุณหมอ!",
  ui_story_5068_50680502_55_dialog_content = "ดี... ดูเหมือนว่าเธอสบายดีแล้ว ซึ่งหมายความว่าเธอสามารถกลับบ้านได้แล้ว",
  ui_story_5068_50680502_56_dialog_content = "คลินิกไม่ปลอดภัยในตอนนี้ ช่วยฉันบอกให้ทุกคนอยู่ห่างไปก่อนเถอะ",
  ui_story_5068_50680502_57_dialog_content = "และอย่าลืมเก็บทุกอย่างที่เกิดขึ้นที่นี่เป็นความลับนะ ตกลงไหม?",
  ui_story_5068_50680502_58_dialog_content = "รับทราบค่ะ! ได้เลยค่ะ!",
  ui_story_5068_50680502_59_dialog_content = "ถ้างั้นฉันจะกลับก่อนแล้ว! ลาก่อนคุณหมอ! ลาก่อนคุณผู้ช่วย!",
  ui_story_5068_50680502_60_dialog_content = "เอลีนอร์... ช่วยกำจัดคนเหล่านี้ให้หน่อยได้มั้ย?",
  ui_story_5068_50680502_61_dialog_content = "—!",
