  ui_story_5068_50680701_24_dialog_content = "ขอโทษที่ทำให้คุณเข้าใจแบบนั้น คุณต้องคิดว่า... ฉันกำลังทำเรื่องแย่ๆ ใช่ไหม?",
  ui_story_5068_50680701_25_dialog_content = "ที่ฉันรู้คือคุณเป็นหมอที่ดีเมื่ออยู่กับผู้ป่วย ไม่มีใครปฏิเสธได้เลย",
