  ui_story_5068_50680901_46_dialog_content = "ถูกต้อง! ถ้าคุณต้องการที่ซ่อนใหม่จากหมาป่าสีดำ ทำไมไม่มากับฉันที่กิลด์เหนือเมฆล่ะ?",
