  ui_story_5068_50681101_16_dialog_content = "อึก...! หุบปาก!",
  ui_story_5068_50681102_1_dialog_content = "ถ้า-ถ้าคุณอยากจะไปหาน้องสาวของฉัน... คุณต้องฆ่าฉันก่อนนะ...",
  ui_story_5068_50681102_2_dialog_content = "ฆ่าคุณหรือ? ขอโทษนะ ฉันไม่โง่พอที่จะเผชิญหน้ากับกิลด์เหนือเมฆโดยตรง",
