  ui_story_5068_50681201_49_dialog_content = "ฉันไม่ชัดเจนพอหรือเปล่า? รีเบคก้าต้องอยู่กับหมาป่าสีดำ",
  ui_story_5068_50681201_50_dialog_content = "ฉันจะไม่ทำร้ายเธอเลยแม้แต่เส้นผมเดียว; สุดท้ายเธอก็เป็นคนเดียวที่สามารถช่วยฉันขยายความรู้เกี่ยวกับหมอกดำ ฉันยินดีที่จะลืมความผิดพลาดในอดีต",
  ui_story_5068_50681201_51_dialog_content = "ฉันยังสามารถแนะนำคุณให้รู้จักกับ<color=#FFB400>ผู้หญิงคนนั้น</color>ที่แนะนำเธอให้ฉันในตอนแรกด้วยค่ะ",
  ui_story_5068_50681201_52_dialog_content = "แต่ถ้าเธอทำผิดเพียงครั้งเดียว... ฮ่าๆๆ ยินดีต้อนรับให้ลองนะเรเบคก้า",
  ui_story_5068_50681201_53_dialog_content = "เพียงรู้ว่าความร่วมมือไม่ใช่เพียงแค่เป็นประโยชน์ที่ดีที่สุดสำหรับคุณเท่านั้น แต่ยังเป็นทางเลือกเดียวที่คุณยังมีอยู่",
  ui_story_5068_50681201_54_dialog_content = "คุณล้อเล่นฉันเหรอ? พูดถึงเรื่องเก่าและผู้หญิงคนหนึ่ง... ชัดเจนว่าเรเบคก้าคือเหยื่อในที่นี้!",
  ui_story_5068_50681201_55_dialog_content = "โอ้? ไม่เป็นไรหาก Caelestite ไม่รู้อะไรเลย แต่คุณ Rebecca? อย่าบอกว่าคุณซ่อนความลับของครอบครัวเพื่อใช้ประโยชน์จากความไว้วางใจของเขา?",
