  ui_story_5068_50681302_7_dialog_content = "ฟู่... ฉัน... ฉันไม่คิดว่าพวกเขาจะไล่ตามเราอีกต่อไป...",
  ui_story_5068_50681302_X7_dialog_content = "ต้องบอกว่าพวกทหารรับจ้างนี่เก่งจริงๆ นะ! แต่เราควรห่วงเรื่องคนที่คุ้มกันให้เราหนีไปมั้ย...?",
  ui_story_5068_50681302_X8_dialog_content = "เราเป็นมืออาชีพทั้งหมด ไม่ต้องห่วงเรื่องพวกเขา เขาจะรวมตัวกับเราในไม่ช้า",
  ui_story_5068_50681302_8_dialog_content = "เราวิ่งมานานแล้ว... ทุกคนยังสบายใช่ไหม?",
  ui_story_5068_50681302_9_dialog_content = "... อย่าหยุดตอนนี้เลย! ที่นี่ไม่ปลอดภัย และอาร์เต้จะไม่ปล่อยให้เราหลุดมือง่ายๆ!",
  ui_story_5068_50681302_10_dialog_content = "...",
  ui_story_5068_50681302_11_dialog_content = "คุณเป็นอย่างไรบ้าง รีเบคก้า? แม้ว่าฉันจะมีแผลบาดเจ็บ แต่คุณยังดูแย่กว่าฉันเสียอีก!",
  ui_story_5068_50681302_12_dialog_content = "ฉัน... ฉันจะไม่เป็นไร... ไปหาที่ปลอดภัยกันก่อนเถอะ...",
  ui_story_5068_50681302_13_dialog_content = "อดทนไว้นะ นางเรคเค้า!",
  ui_story_5068_50681302_14_dialog_content = "ข้างหน้ามีคลังสินค้าที่ถูกทิ้งไว้บ้าง เราสามารถหยุดและหายใจสักพักที่นั่น!",
  ui_story_5068_50681302_15_dialog_content = "ฉันและทหารของฉันจะคอยดูแล ดังนั้นเธอก็ไปพักผ่อนเถอะ เราจะไม่อยู่ที่นี่นานเท่าไหร่",
