  ui_story_5068_50681302_19_dialog_content = "...",
  ui_story_5068_50681302_20_dialog_content = "เพียงพอ, อิซ่า... ฉันไม่อยากรู้นะคะ",
  ui_story_5068_50681302_21_dialog_content = "เอลีนอร์เสี่ยงชีวิตเพื่อช่วยฉันจากหมาป่าดำสองครั้งแล้ว... นั่นคือสิ่งที่ฉันต้องรู้... ไม่มีอะไรเพิ่มเติม",
