  ui_story_5068_50681402_14_dialog_content = "หมอกนี้... เคยเป็นพ่อแม่ที่ล้ำค่าของคุณ",
  ui_story_5068_50681402_15_dialog_content = "— ?!",
  ui_story_5068_50681402_16_dialog_content = "หลังจากวิจัยเป็นเวลาหนึ่งปีเต็ม ฉันสุดท้ายก็ค้นพบความลับของตระกูลสวานโดนา: พ่อแม่ในครอบครัวของคุณมีผลต้านทาน แม้กระทั่งทำลายความสามารถของลูกของพวกเขา",
  ui_story_5068_50681402_17_dialog_content = "เพราะสิ่งนี้เอง รีเบคก้า ที่ฉันสามารถควบคุมคุณให้ประพฤติดี ฉันควรขอบคุณพ่อแม่ของคุณที่ช่วยลดความพยายามของฉันลงเยอะเลย",
  ui_story_5068_50681402_18_dialog_content = "H-ทำไมถึงทำใจร้ายแบบนี้กันล่ะ? นำครอบครัวของเธอมาใช้ต่อต้านเธอ...",
  ui_story_5068_50681402_19_dialog_content = "อาร์เต้! คุณ... คุณเสียสติหรือเปล่า?! คุณจำไม่ได้หรือว่าคุณเคยสอนเราอะไร?! \"คนที่เลวที่สุดในโลกคือคนที่ทำร้ายคนอ่อนแอโดยไม่อายหน้า!\"",
  ui_story_5068_50681402_20_dialog_content = "ดูสารรูปตัวเองตอนนี้สิ! แม้แต่ปีที่แล้วฉันยังเห็นอกเห็นใจคุณบ้าง เพราะคิดว่าคุณแค่ต้องการแก้แค้น แต่ตอนนี้ฉันเห็นว่าคุณเป็นคนที่แตกต่างไปอย่างสิ้นเชิง!",
  ui_story_5068_50681402_21_dialog_content = "อะไรที่ทำให้คุณเสียสติไปถึงขนาดนี้? หรือเพราะความเข้าใจผิดเกี่ยวกับอำนาจและการฆ่า?",
  ui_story_5068_50681402_22_dialog_content = "หรือว่าเธอเป็นแบบนี้ตั้งแต่แรกเลยเหรอ? เธอใช้เราตั้งแต่เริ่มต้น...?",
  ui_story_5068_50681402_23_dialog_content = "ฮิฮิ... ฮ่าฮ่าฮ่า! คุณรู้อะไรเหรอ?!",
  ui_story_5068_50681402_24_dialog_content = "ฉันเจอคุณหิวโหยในขยะ น่าสงสารจนแม้กระทั่งหมายังดูถูก! คุณคิดว่าตอนนี้คุณจะอยู่ที่ไหนถ้าไม่มีฉัน?!",
  ui_story_5068_50681402_25_dialog_content = "พวกหมาป่าดำคงไม่สามารถอยู่รอดมานานขนาดนี้หากฉันไม่ได้โกหก หลอกลวง และลักขโมยทุกขั้นตอน!",
  ui_story_5068_50681402_26_dialog_content = "นี่เป็นเหตุผลที่แกทำให้พี่น้องในหมาป่าสีดำกลายเป็นเครื่องมือเพื่อประโยชน์ส่วนตัวของแกหรือเปล่า?!",
  ui_story_5068_50681402_27_dialog_content = "ถ้างั้น การทรยศคุณคือการตัดสินใจที่ฉลาดที่สุดในชีวิตของฉัน",
  ui_story_5068_50681402_28_dialog_content = "พอได้แล้ว!",
  ui_story_5068_50681402_29_dialog_content = "<color=#e8d9bb>คลิก</color>",
  ui_story_5068_50681402_30_dialog_content = "... คนทรยศไม่มีสิทธิ์วิจารณ์หมาป่าสีดำ",
  ui_story_5068_50681402_31_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5068_50681402_32_dialog_content = "เฮ้ ดูเหมือนว่าการยิงของคุณผู้กำกับเริ่มขึ้นสนิมแล้วนะ",
  ui_story_5068_50681402_33_dialog_content = "ชิ",
  ui_story_5068_50681402_34_dialog_content = "<color=#e8d9bb>ปัง ปัง ปัง!</color>",
  ui_story_5068_50681402_35_dialog_content = "ไม่... หยุดเถอะ... โอย...",
  ui_story_5068_50681402_36_dialog_content = "การดิ้นรนจนถึงที่สุดก็ไม่มีประโยชน์อะไรเลยนะ รีเบคก้า",
  ui_story_5068_50681402_37_dialog_content = "ไม่ว่าจะตายหรือมีชีวิต ฉันก็ยังใช้พวกคุณในการวิจัยต่อไป ดังนั้นอย่าพูดว่าฉันไม่เคยให้โอกาสให้คุณอยู่รอด! ทุกคนจะต้องตายที่นี่!",
