  ui_story_5068_50681402_39_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5068_50681402_40_dialog_content = "<color=#e8d9bb>ซ่า!</color>",
  ui_story_5068_50681402_41_dialog_content = "<size=50>เอลีนอร์?!</size>",
