  ui_story_5068_50681402_45_dialog_content = "ครับ!!!",
  ui_story_5068_50681402_46_dialog_content = "เอลีนอร์... เธอได้ยินฉันมั้ย...?",
  ui_story_5068_50681402_47_dialog_content = "เรเบคก้า... ฉันไม่เคยคิดว่าฉันจะได้ยินเสียงเธอ... เรียกชื่อฉันอีกครั้ง... ฉันคิดว่าเธอจะทิ้งฉันไป",
