  ui_story_5068_50681501_33_dialog_content = "ทำไม? ทำไมมันต้องเป็นแบบนี้...?",
  ui_story_5068_50681501_34_dialog_content = "ครอบครัวของฉันหายไปแล้ว อีลีนอร์หายไป บ้านของเราหายไป และแม้กระทั่งต่างหูที่เธอทำให้ฉันก็หายไป—ฉันไม่มีอะไรเหลือเลย",
  ui_story_5068_50681501_35_dialog_content = "ไม่จริงนะเรเบคก้า! แล้วอีซ่าล่ะ? คุณยังมีน้องสาวอยู่นะ!",
  ui_story_5068_50681501_36_dialog_content = "โอย...",
  ui_story_5068_50681501_37_dialog_content = "เร... เบคก้า...",
  ui_story_5068_50681501_38_dialog_content = "... ขอบคุณสวรรค์ เธอยังไม่ตาย!",
  ui_story_5068_50681501_39_dialog_content = "ที่ล่างนั้นอันตรายเกินไปนะเรเบคก้า! อีซ่ายังต้องการคุณอยู่ โปรดกลับมาเถอะ!",
  ui_story_5068_50681501_40_dialog_content = "อิซ่า... ต้องการฉัน...?",
  ui_story_5068_50681501_41_dialog_content = "น-น้องสาวของฉันยังต้องการฉันเสียน่ะ!",
  ui_story_5068_50681501_42_dialog_content = "(คุณแน่ใจหรือ? สุดท้ายแล้วใครจะต้องการคนที่นำความเจ็บปวดและทุกข์ทรมานไปให้ทุกที่ที่เธอไปกันเนี่ย?)",
  ui_story_5068_50681501_43_dialog_content = "ฉันเองครับ... ฉันคือคนที่ทำทุกอย่างนี้...",
  ui_story_5068_50681501_44_dialog_content = "(สิ่งที่เธอเรียกว่า \"ของขวัญ\" นั้นเป็นต้นเหตุของความทุกข์ทั้งหมดนี้ คุณคิดจริง ๆ หรือว่าคุณคู่ควรที่จะให้ชีวิตต่อไป?)",
  ui_story_5068_50681501_45_dialog_content = "ถูกต้อง... พลังของฉันคือสิ่งที่นำหมาป่าสีดำมายังบ้านของครอบครัวเรา ด้วยเหตุผลเพราะฉัน เขาทั้งหมด...",
  ui_story_5068_50681501_46_dialog_content = "พลังของฉันเป็นสิ่งที่สร้างหมอกสีดำที่ทำให้คนเยอะ ๆ ในสลัมป่วย...",
  ui_story_5068_50681501_47_dialog_content = "(เอลีนอร์ล่ะ? ความตายของเธอก็เป็นความผิดของคุณ และอย่าลืมเรื่องพี่สาวของคุณที่มีหนึ่งขาอยู่ในหลุมศพแล้ว)",
  ui_story_5068_50681501_48_dialog_content = "(คุณไม่ได้คิดจริงๆว่าคุณสามารถเอาชนะหมาป่าดำด้วยพลังต้องสาปเช่นของคุณใช่ไหม?)",
  ui_story_5068_50681501_49_dialog_content = "(และแม้ว่าคุณจะทำได้ ใครจะรับรองว่าไม่มีใครอื่นมาตามหาพลังของคุณ? คุณสูญเสีย Eleanor ไปแล้ว ครั้งหน้าใครจะเสียค่าใช้จ่าย? คนในสลัม? Isa?)",
  ui_story_5068_50681501_50_dialog_content = "ไม่! ฉันจะไม่ยอมให้เกิดเรื่องนั้น... แต่วิธีไหน... ฉันจะปกป้องพวกเขาได้อย่างไร?",
  ui_story_5068_50681501_51_dialog_content = "(หึหึ คำตอบก็ง่ายนิดเดียว คุณแค่ต้องทำ...)",
  ui_story_5068_50681501_52_dialog_content = "(กำจัดการมีอยู่ของคุณในโลกนี้ พอคุณหายไป ทุกอย่างจะดีขึ้น...)",
  ui_story_5068_50681501_53_dialog_content = "*แค่ก ๆ* โอย... เจ็บจัง!",
  ui_story_5068_50681501_54_dialog_content = "ตื่นแล้วเหรอ คุณอีซ่า!",
  ui_story_5068_50681501_55_dialog_content = "โง่... หยุดเป็นห่วงฉัน... รีเบคก้าคือคนที่ต้องการ... อ๊าก—",
  ui_story_5068_50681501_56_dialog_content = "หยุดเคลื่อนไหว! ถ้านายยังคงเคลื่อนไหว นายจะเสียเลือดมากขึ้นเท่านั้น...",
  ui_story_5068_50681501_57_dialog_content = "คุณต้องหยุดเธอ... เธอดูเหมือนกำลังจะทำสิ่งที่สะเพร่า...",
  ui_story_5068_50681501_58_dialog_content = "ฉัน...ฉันเป็นพี่สาวเธอ... ฉันรู้ว่าเธอเป็นแบบไหน ตอนนี้ไปหยุดเธอเถอะ...",
  ui_story_5068_50681501_59_dialog_content = "ค-ครับ!",
  ui_story_5068_50681501_60_dialog_content = "เรเบคก้า!",
  ui_story_5068_50681501_61_dialog_content = "เรเบคก้า? เธอกำลัง...?",
  ui_story_5068_50681501_62_dialog_content = "... อย่าเข้ามาใกล้นะ!",
  ui_story_5068_50681501_63_dialog_content = "ที่นี่อันตรายนะ",
  ui_story_5068_50681501_64_dialog_content = "เธอคิดจะทำอะไร",
  ui_story_5068_50681501_65_dialog_content = "... สิ่งเดียวที่ฉันสามารถทำเพื่อหยุดทำร้ายคนรอบข้างฉัน",
  ui_story_5068_50681501_66_dialog_content = "ย-คุณดูดซับพิษทั้งหมดเหรอ?!",
  ui_story_5068_50681501_67_dialog_content = "แต่ร่างกายของเธอ... จริง ๆ แล้วรับไหวกับปริมาณเยอะขนาดนั้นเหรอ?!",
  ui_story_5068_50681501_68_dialog_content = "ฉันจะไม่เป็นไร... ไม่ต้องห่วง มันไม่เจ็บเลย...",
  ui_story_5068_50681501_69_dialog_content = "เอิ่ม...!",
  ui_story_5068_50681501_70_dialog_content = "พอเถอะเรเบคก้า! ถ้าไม่หยุดเธอจะตายนะ!",
  ui_story_5068_50681501_71_dialog_content = "ถูกต้อง... ฉันทำสิ่งนี้เพื่อความเป็นสิ่งที่ดีของทุกคน...",
  ui_story_5068_50681501_72_dialog_content = "PlayerName... ฉันควรจะตายไปนานแล้ว ฉันไม่รู้ว่าทำไมฉันถึงคิดว่าฉันสามารถปกป้องใครได้...",
  ui_story_5068_50681501_73_dialog_content = "อย่าพูดแบบนั้นสิ! คุณสัญญากับฉันว่าคุณจะไม่ทำร้ายตัวเองอีกแล้วนะ!",
  ui_story_5068_50681501_74_dialog_content = "เอิ่ม, คงต้องย้อนกลับคำพูดของผม... นี่เป็นอัมบราตันเสียที คุณไม่สามารถเชื่อทุกอย่างที่คุณได้ยินในเมืองนี้",
  ui_story_5068_50681501_75_dialog_content = "อัมบราตันไม่เกี่ยวข้องกับเรื่องนี้เลย รีเบคก้า! คุณไม่ใช่คนแบบนั้น หยุดเถอะ! คิดถึงอิซ่าสิ! คุณสุดท้ายก็มีโอกาสได้พบน้องสาวของคุณอีกครั้ง!",
  ui_story_5068_50681501_76_dialog_content = "อึก...ไอ ไอ...",
  ui_story_5068_50681501_77_dialog_content = "อิซ่า... ขอโทษนะ... แต่... คุณช่วย... จับตาดูเธอให้ฉันหน่อยได้ไหม...?",
  ui_story_5068_50681501_78_dialog_content = "กรุณาบอกเธอให้ทราบว่าฉันขอโทษ... และว่านี่เป็นวิธีเดียวในการหยุดทุกอย่าง ฉันทำสิ่งนี้เพื่อเธอด้วย",
  ui_story_5068_50681501_79_dialog_content = "(ถูกต้องแล้ว ถ้าเธอต้องการให้สิ่งนี้จบ ก็ดูดซับพิษนี้เข้าไป! รับมันทั้งหมดเถอะ!!!)",
  ui_story_5068_50681501_80_dialog_content = "PlayerName... ขอร้อง... ช่วยพาพี่สาวฉันออกจากที่นี่.",
  ui_story_5068_50681501_81_dialog_content = "เรเบคก้า...",
  ui_story_5068_50681501_82_dialog_content = "ไป... ตอนนี้—!!",
  ui_story_5068_50681501_83_dialog_content = "อ๊ากกก—!!!",
  ui_story_5068_50681501_84_dialog_content = "น่าจะพอแล้วนะคะ รีเบคก้า...",
  ui_story_5068_50681501_85_dialog_content = "ที่เหลือให้ฉันดูแลเอง",
  ui_story_5068_50681501_86_dialog_content = "ผู้กำกับ! รีเบคก้ายังมีชีวิตอยู่ และดูเหมือนว่าเธอดูดซับพิษจำนวนมากเข้าไปในตัว?",
  ui_story_5068_50681501_87_dialog_content = "แต่ยังไงล่ะ?! เธอหาพิษขนาดนี้ได้จากไหนเนี่ย...?",
  ui_story_5068_50681501_88_dialog_content = "มันมาจากโถที่แตกนั่นแหละ... ร่างกายของเธอเริ่มเปลี่ยนแปลงจากการดูดซับมากเกินไป!",
  ui_story_5068_50681501_89_dialog_content = "... ดังนั้น เธอกำลังใช้พิษจากกระปุกเหล่านั้นเป็น \"ยาแก้พิษ\" เหรอ?",
  ui_story_5068_50681501_90_dialog_content = "ฉันไม่คิดว่าฉันจะสามารถควบคุมเธอได้เมื่อเธอดูดยาพิษทั้งหมดเข้าไป... ดูเหมือนว่า—",
  ui_story_5068_50681501_91_dialog_content = "\"ดูเหมือนว่าทางเลือกเดียวของฉันคือการหนีไป\" นั่นเป็นคำที่คุณกำลังจะพูดใช่ไหม?",
  ui_story_5068_50681501_92_dialog_content = "เชโอล...",
  ui_story_5068_50681501_93_dialog_content = "ประเมินสถานการณ์รอบ ๆ คลินิกแล้วรายงานกลับมาหาฉัน! ดูแลตัวเองดี ๆ นอกนั้นนะ!",
  ui_story_5068_50681501_94_dialog_content = "ใช่ค่ะ, เลดี้เชล!",
  ui_story_5068_50681501_95_dialog_content = "เสียง: ดังนั้น คุณยังจำฉันได้หลังจากนี้ทั้งหมด, อาร์เต้ของหมาป่าสีดำ",
  ui_story_5068_50681501_96_dialog_content = "... คลินิกที่สภาพไม่ดีอย่างนี้ไม่ควรน่าสนใจคุณหรือกิลด์เหนือเมฆ ทำไมคุณถึงพาคนของคุณมาที่นี่?",
  ui_story_5068_50681501_97_dialog_content = "\"ไม่ควรสนใจ\" คุณพูดงั้นเหรอ? อิซ่าน้อยของเราที่กระฉับกระเฉงนอนบาดเจ็บอยู่บนพื้น และดูเหมือนว่า PlayerName ก็อยู่ในความเสี่ยงที่จะเสียชีวิตเช่นกัน",
  ui_story_5068_50681501_98_dialog_content = "บอกฉันสิ ฉันควรจัดการเรื่องนี้อย่างไรให้เป็นไปตามกฎของเรา?",
  ui_story_5068_50681501_99_dialog_content = "ตามกฎหมาย กิลด์เหนือเมฆไม่มีอำนาจในสลัมเหล่านี้",
  ui_story_5068_50681501_100_dialog_content = "ขออภัยที่ทำให้คุณผิดหวัง แต่ตั้งแต่วันนี้เป็นต้นไป กิลด์เหนือเมฆจะดูแลคลินิกนี้",
  ui_story_5068_50681501_101_dialog_content = "ตอนนี้คุณจะตอบแทนเรายังไงสำหรับสิ่งที่คุณทำต่อหมอของเราคนหนึ่ง?",
  ui_story_5068_50681501_102_dialog_content = "...",
  ui_story_5068_50681501_103_dialog_content = "ท่านหญิงเชโอล! อีซ่าและ PlayerName ปลอดภัยในขณะนี้ แต่สถานการณ์ของเรเบคก้าดูไม่ค่อยดี! คนอื่น ๆ ของเราก็ถอยกลับไปแล้ว!",
  ui_story_5068_50681501_104_dialog_content = "อย่าบอกนะว่า...",
  ui_story_5068_50681501_105_dialog_content = "เลดี้เชล! คุณมาที่นี่ในที่สุดแล้ว!",
  ui_story_5068_50681501_106_dialog_content = "เล-เลดี้เชล! นี่เรเบคก้า... ท่านต้องช่วยเธอ—",
  ui_story_5068_50681501_107_dialog_content = "ตาย-!!!",
  ui_story_5068_50681501_108_dialog_content = "... สาวน้อยผู้น่าสงสาร ดูสิว่าพวกเขาทำอะไรกับเธอ",
  ui_story_5068_50681501_109_dialog_content = "ผู้อำนวยการ! เราควร... ถอยก่อนเถอะ?",
  ui_story_5068_50681501_110_dialog_content = "ไม่! ใช้ระเบิดหมอกสีดำนะ!",
  ui_story_5068_50681501_111_dialog_content = "<color=#e8d9bb>ฟู่—</color>",
  ui_story_5068_50681501_112_dialog_content = "ไม่ได้ผลงั้นเหรอ?! แต่ทำไม—",
  ui_story_5068_50681501_113_dialog_content = "ศิลปะ!!!",
  ui_story_5068_50681501_114_dialog_content = "ฉันมีงานใหม่ให้คุณ PlayerName! นำกำลังของเราเข้าสู่การต่อสู้!",
  ui_story_5068_50681501_115_dialog_content = "เรเบคก้าต้องการความช่วยเสริมจากพวกเราเดี๋ยวนี้เลย!",
  ui_story_5068_50681501_116_dialog_content = "... ก-เข้าใจแล้วครับ!",
  ui_story_5068_50681502_1_dialog_content = "โยนระเบิดเพิ่มเถอะคุณโง่! ทิ้งทุกอย่างที่เรามีใส่เธอเถอะ!",
  ui_story_5068_50681502_2_dialog_content = "แต่คุณผู้อำนวยการ! ถ้าเราใช้จำนวนมากเท่านั้นพร้อมกัน อุปกรณ์ป้องกันของเราก็ไม่สามารถช่วยเราได้! นอกจากนี้ ทุกคนก็เริ่ม...",
  ui_story_5068_50681502_3_dialog_content = "อย่าถามฉัน! เราต้องไม่ยอมให้ผู้หญิงบ้าๆ นั่นตามมาทันเรา!",
  ui_story_5068_50681502_4_dialog_content = "*ไอ ๆ* มัน-มันสายเกินไปแล้ว พวกเราหายใจเข้าไปแล้ว... อ๊ากกก...",
  ui_story_5068_50681502_5_dialog_content = "...",
  ui_story_5068_50681502_6_dialog_content = "คุณที่นั่น! พานักสู้ของเราไปบ้าง และอย่าปล่อยให้อาร์เต้หลุดพ้น ส่วนคนอื่น ๆ ช่วยกันเก็บกวาดความยุ่งเหยิงนี้",
  ui_story_5068_50681502_7_dialog_content = "ค่ะ!",
  ui_story_5068_50681502_8_dialog_content = "เร... เรเบคก้า...",
  ui_story_5068_50681502_9_dialog_content = "ฉันเอง... อิซ่า... ตื่นเถอะค่ะ...",
  ui_story_5068_50681502_10_dialog_content = "...",
  ui_story_5068_50681502_11_dialog_content = "อืม... ฉัน... อยู่ที่ไหน...?",
  ui_story_5068_50681502_12_dialog_content = "เรเบคก้า! ในที่สุดคุณก็ตื่นแล้ว!",
  ui_story_5068_50681502_13_dialog_content = "โอ๊ะ ขอบคุณสวรรค์—นึกว่าฉันจะทำให้เรเบคก้าหายไปอีกแล้วเสีย!",
  ui_story_5068_50681502_14_dialog_content = "—!!",
  ui_story_5068_50681502_15_dialog_content = "รอสักครู่ รีเบคก้า! คุณ-คุณจะไปไหนน่ะ?!",
  ui_story_5068_50681502_16_dialog_content = "ย-อย่าเข้าใกล้ฉันนะ!",
  ui_story_5068_50681502_17_dialog_content = "ฉันคิดว่าเมื่อสักครู่นี้ฉันกลายเป็นสิ่งอื่น... หมอกนี้ และผู้คนที่ได้รับบาดเจ็บเหล่านี้... นี่ฉันเป็นคนทำให้เกิดขึ้นเหรอ?",
  ui_story_5068_50681502_18_dialog_content = "ฉันแค่อยากจบเรื่องทุกอย่าง แต่กลับทำให้ทุกคนเจ็บปวดอีกครั้ง... ฉันน่าจะไม่มีความหวังจริงๆ ใช่ไหม? ฉันไม่อยากเป็นปัญหาให้ทุกคนอีกต่อไป ดังนั้นก็ปล่อยฉันคนเดียวเถอะ—",
  ui_story_5068_50681502_19_dialog_content = "อย่าเป็นคนโง่นะเรเบคก้า!",
  ui_story_5068_50681502_20_dialog_content = "อิซ่า?!",
  ui_story_5068_50681502_21_dialog_content = "ไม่! ปล่อยฉัน! ร่างกายฉัน—มันเต็มไปด้วยพิษ!",
